function Button({ children, variant = 'primary', className = '', onClick, type = 'button', disabled = false }: { children: React.ReactNode; variant?: 'primary' | 'outline' | 'ghost' | 'warm'; className?: string; onClick?: () => void; type?: 'button' | 'submit'; disabled?: boolean }) {
  const styles = { primary: 'bg-[#1e8f87] text-white hover:bg-[#187a73]', outline: 'border border-[#cbd5ce] bg-[#fbfaf5] text-[#27403b] hover:border-[#1e8f87] hover:text-[#1e8f87]', ghost: 'text-[#61716c] hover:bg-[#e7eee8] hover:text-[#24423d]', warm: 'bg-[#edbc55] text-[#20322f] hover:bg-[#e7a93b]' };
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all duration-200 active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} data-testid="button-action">{children}</button>;
}

