function Stat({ label, value, suffix }: { label: string; value: string; suffix: string }) { return <div><p className="mono text-3xl font-medium text-[#1e8f87]">{value}<span className="text-lg">{suffix}</span></p><p className="mt-1 text-sm text-[#687871]">{label}</p></div>; }
function Feature({ icon, number, title, text }: { icon: React.ReactNode; number: string; title: string; text: string }) { return <div className="rounded-2xl border border-[#dce4da] bg-[#fbfaf5] p-5"><div className="flex items-center justify-between"><span className="text-[#1e8f87] [&>svg]:size-5">{icon}</span><span className="mono text-[10px] text-[#a6b0aa]">{number}</span></div><h3 className="mt-8 font-bold text-[#20322f]">{title}</h3><p className="mt-2 text-sm leading-6 text-[#718079]">{text}</p></div>; }

function HowItWorks() { return <PublicPage eyebrow="The adaptive loop" title={<>A path that pays attention to <span className="text-[#1e8f87]">you.</span></>}>{<div className="mt-16 space-y-5">{[['01', 'Tell us where you are going', 'Choose a career destination, a realistic timeline, and the hours you can protect. Your plan begins with your life, not a blank calendar.', Target], ['02', 'Make the invisible visible', 'A focused assessment surfaces your strengths and the concepts between today and the work you want to do.', Radar], ['03', 'Follow a small next step', 'Each day has a clear action, a reason it was chosen, and a way to prove you have it.', ListChecks], ['04', 'Let progress reshape the route', 'Complete a project, change your pace, or get stuck. LearnPath adjusts the emphasis without losing the destination.', TrendingUp]].map(([num, head, body, Icon]) => <div key={num as string} className="grid gap-5 rounded-2xl border border-[#dce4da] bg-[#fbfaf5] p-6 md:grid-cols-[70px_1fr_48px] md:items-center"><span className="mono text-sm text-[#b17820]">{num as string}</span><div><h2 className="display text-2xl font-bold text-[#20322f]">{head as string}</h2><p className="mt-2 max-w-2xl text-sm leading-7 text-[#718079]">{body as string}</p></div><span className="grid size-11 place-items-center rounded-xl bg-[#e3eee7] text-[#1e8f87]"><Icon size={20} /></span></div>)}</div>}</PublicPage>; }
function Features() { return <PublicPage eyebrow="Built around momentum" title={<>A quieter kind of <span className="text-[#1e8f87]">intelligence.</span></>}>{<div className="mt-16 grid gap-5 md:grid-cols-2">{[['Adaptive roadmap', 'A living sequence of phases, projects, and checkpoints that stays tied to your goal.', Compass], ['Skill intelligence', 'See self-reported confidence beside verified evidence. Know which gaps deserve your attention.', ShieldCheck], ['Resource context', 'No endless catalogs. Every resource earns its place with a short explanation of why it is here.', BookOpen], ['Learning assistant', 'Ask for a simpler explanation, a hint, or a different example without breaking your flow.', Bot], ['Progress signals', 'Weekly hours, confidence, and completed work in one honest picture of momentum.', TrendingUp], ['Privacy by default', 'Your learning profile belongs to you. The first build keeps every interaction local and transparent.', LockKeyhole]].map(([head, body, Icon], i) => <div key={head as string} className={`rounded-2xl border border-[#dce4da] p-7 ${i === 0 ? 'bg-[#265048] text-[#f8f5eb]' : 'bg-[#fbfaf5]'}`}><span className={`grid size-11 place-items-center rounded-xl ${i === 0 ? 'bg-[#edbc55] text-[#20322f]' : 'bg-[#e3eee7] text-[#1e8f87]'}`}><Icon size={21} /></span><h2 className={`display mt-8 text-2xl font-bold ${i === 0 ? 'text-[#f8f5eb]' : 'text-[#20322f]'}`}>{head as string}</h2><p className={`mt-3 text-sm leading-7 ${i === 0 ? 'text-[#c6d7cc]' : 'text-[#718079]'}`}>{body as string}</p></div>)}</div>}</PublicPage>; }
function About() { return <PublicPage eyebrow="Why we made this" title={<>Less content. More <span className="text-[#1e8f87]">becoming.</span></>}>{<div className="mt-16 grid gap-10 md:grid-cols-[1fr_1.3fr]"><div className="rounded-3xl bg-[#edbc55] p-8"><Sparkles className="text-[#20322f]" /><p className="display mt-24 text-3xl font-bold leading-tight text-[#20322f]">The hard part of learning is rarely finding one more thing to read.</p></div><div className="space-y-6 text-lg leading-9 text-[#61716c]"><p>LearnPath started with a simple frustration: talented people spend too much energy choosing what to learn and too little energy practicing the work they care about.</p><p>We believe a good learning product should feel like a thoughtful coach. It should remember your context, point to the next useful challenge, and explain the reasoning without pretending the route is fixed.</p><p className="font-bold text-[#20322f]">The goal is not to finish a catalog. It is to become capable.</p></div></div>}</PublicPage>; }

function Auth({ register = false }: { register?: boolean }) { const [, setLocation] = useLocation(); const [email, setEmail] = useState(''); const [showDetails, setShowDetails] = useState(register); return <div className="grid min-h-[100dvh] lg:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-[#265048] p-10 text-[#f8f5eb] lg:flex lg:flex-col lg:justify-between"><Logo light /><div><p className="mono text-xs uppercase tracking-[.2em] text-[#edbc55]">Your route, made visible</p><h1 className="display mt-5 max-w-md text-6xl font-bold leading-[.92] tracking-[-.06em]">Small steps. Serious <span className="text-[#edbc55]">momentum.</span></h1><p className="mt-6 max-w-md leading-7 text-[#bfd1c4]">LearnPath helps you make the next decision with confidence — then gives you a reason to keep going.</p></div><p className="mono text-xs text-[#8da99b]">LEARNPATH AI / PRIVATE BETA</p></div><div className="flex flex-col bg-[#f7f5ed] px-6 py-8 md:px-16"><div className="lg:hidden"><Logo /></div><div className="mx-auto flex w-full max-w-md flex-1 flex-col justify-center"><p className="mono text-xs uppercase tracking-[.18em] text-[#b17820]">{register ? 'Start with context' : 'Welcome back'}</p><h1 className="display mt-3 text-4xl font-bold tracking-[-.04em] text-[#20322f]">{register ? 'Build a path that fits.' : 'Pick up where you left off.'}</h1><p className="mt-3 text-sm leading-6 text-[#718079]">{register ? 'Tell us a little more about yourself so your first recommendations feel personal.' : 'Your Deep Learning phase is waiting for today’s next step.'}</p><form className="mt-9 space-y-4" onSubmit={(e) => { e.preventDefault(); setLocation(register ? '/onboarding' : '/dashboard'); }}><label className="block text-sm font-bold text-[#36504a]">Email address<input value={email} onChange={e => setEmail(e.target.value)} type="email" required placeholder="you@example.com" className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3.5 text-sm outline-none focus:border-[#1e8f87] focus:ring-2 focus:ring-[#1e8f87]/10" data-testid="input-email" /></label>{register && <><label className="block text-sm font-bold text-[#36504a]">Your name<input defaultValue="Maya Chen" required className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3.5 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-name" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-bold text-[#36504a]">Current role<input placeholder="e.g. Student, Developer" className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-role" /></label><label className="block text-sm font-bold text-[#36504a]">Experience<select defaultValue="" className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-3 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="select-experience"><option value="" disabled>Select</option><option>Just starting</option><option>1–2 years</option><option>3–5 years</option><option>5+ years</option></select></label></div><label className="block text-sm font-bold text-[#36504a]">What are you hoping to accomplish?<textarea rows={3} placeholder="Tell us about the role, project, or change you are working toward." className="mt-2 w-full resize-none rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="textarea-registration-goal" /></label><button type="button" onClick={() => setShowDetails(!showDetails)} className="text-left text-xs font-bold text-[#1e8f87]" data-testid="button-more-registration-details">{showDetails ? 'Hide extra details' : 'Add more about yourself'} <ChevronDown size={13} className={`ml-1 inline transition-transform ${showDetails ? 'rotate-180' : ''}`} /></button>{showDetails && <label className="block text-sm font-bold text-[#36504a]">A little more about you<textarea rows={4} placeholder="Your interests, background, or what motivates you to learn." className="mt-2 w-full resize-none rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="textarea-registration-about" /></label>}</>}<label className="block text-sm font-bold text-[#36504a]">Password<input type="password" required placeholder="••••••••" className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3.5 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-password" /></label><Button type="submit" className="mt-3 w-full">{register ? 'Continue to my profile' : 'Sign in to LearnPath'} <ArrowRight size={16} /></Button></form><div className="my-7 flex items-center gap-3 text-xs text-[#a1ada7]"><span className="h-px flex-1 bg-[#dce4da]" /> or <span className="h-px flex-1 bg-[#dce4da]" /></div><Button variant="outline" className="w-full" onClick={() => setLocation(register ? '/onboarding' : '/dashboard')}><Mail size={16} /> Continue with email link</Button>{!register && <><div className="my-4 flex items-center gap-3 text-xs text-[#a1ada7]"><span className="h-px flex-1 bg-[#dce4da]" />or<span className="h-px flex-1 bg-[#dce4da]" /></div><button type="button" onClick={() => setLocation('/admin/login')} className="flex w-full items-center justify-center gap-2 rounded-xl border border-[#ccd8ce] bg-[#f7f5ed] px-4 py-3 text-sm font-bold text-[#36504a] transition hover:border-[#1e8f87] hover:bg-[#eef5ef]"><ShieldCheck size={16} className="text-[#1e8f87]" /> Admin login</button></>}<p className="mt-8 text-center text-sm text-[#718079]">{register ? 'Already have a path?' : 'New to LearnPath?'} <Link href={register ? '/login' : '/register'} className="font-bold text-[#1e8f87]" data-testid="link-auth-switch">{register ? 'Sign in' : 'Create an account'}</Link></p></div></div></div>; }

const navItems = [
  { href: '/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/learning-path', label: 'Learning path', icon: Compass },
  { href: '/resources', label: 'Resources', icon: BookOpen }, { href: '/projects', label: 'Projects', icon: BriefcaseBusiness },
  { href: '/skills', label: 'Skills', icon: Radar }, { href: '/progress', label: 'Progress', icon: TrendingUp },
];
const moreItems = [{ href: '/assessments', label: 'Assessments', icon: ListChecks }, { href: '/assistant', label: 'AI assistant', icon: Bot }, { href: '/notifications', label: 'Notifications', icon: Bell }];

function AppShell({ children }: { children: React.ReactNode }) {
  const [location, setLocation] = useLocation(); const [mobile, setMobile] = useState(false);
  const logout = () => setLocation('/');
  return <div className="min-h-[100dvh] bg-[#f3f4ed] text-[#20322f]"><aside className="fixed inset-y-0 left-0 z-40 hidden w-[254px] flex-col border-r border-[#dbe4da] bg-[#265048] text-[#deebe0] lg:flex"><div className="px-6 py-6"><Logo light /></div><div className="px-3"><p className="mono mb-3 px-3 text-[10px] uppercase tracking-[.18em] text-[#88a99b]">Workspace</p>{navItems.map(item => <SideLink key={item.href} {...item} active={location === item.href} />)}<p className="mono mb-3 mt-8 px-3 text-[10px] uppercase tracking-[.18em] text-[#88a99b]">Keep learning</p>{moreItems.map(item => <SideLink key={item.href} {...item} active={location === item.href} />)}</div><div className="mt-auto space-y-2 p-4"><Link href="/profile" className="flex items-center gap-3 rounded-2xl border border-[#4e7068] bg-[#305248] p-3" data-testid="link-sidebar-profile"><span className="grid size-9 place-items-center rounded-xl bg-[#edbc55] text-xs font-bold text-[#20322f]">MC</span><span className="min-w-0"><span className="block truncate text-sm font-bold">Maya Chen</span><span className="block text-xs text-[#9eb8aa]">AI Engineer track</span></span><ChevronRight size={15} className="ml-auto text-[#8da99b]" /></Link><button onClick={logout} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-[#abc1b3] hover:bg-[#305248] hover:text-[#f8f5eb]" data-testid="button-logout"><span className="grid size-5 place-items-center rounded-md border border-[#6f9182] text-xs">↗</span>Log out</button></div></aside><div className="lg:pl-[254px]"><header className="sticky top-0 z-30 flex h-[70px] items-center justify-between border-b border-[#dbe4da] bg-[#f3f4ed]/90 px-5 backdrop-blur-md lg:px-9"><div className="flex items-center gap-3"><button onClick={() => setMobile(!mobile)} className="rounded-lg p-2 lg:hidden" data-testid="button-open-sidebar"><Menu size={20} /></button><div className="lg:hidden"><Logo /></div><div className="hidden items-center gap-2 text-sm text-[#7b8882] md:flex"><span>Tuesday, April 22</span><span className="text-[#c5cdc5]">/</span><span className="font-bold text-[#36504a]">Week 12</span></div></div><div className="flex items-center gap-2"><Link href="/notifications" className="relative rounded-xl p-2.5 text-[#61716c] hover:bg-[#e4ebe2]" data-testid="link-header-notifications"><Bell size={18} /><span className="absolute right-2 top-2 size-1.5 rounded-full bg-[#e6a933]" /></Link><Link href="/assistant" className="hidden items-center gap-2 rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-3 py-2 text-xs font-bold text-[#36504a] sm:flex" data-testid="link-header-assistant"><Bot size={15} className="text-[#1e8f87]" /> Ask your coach</Link></div></header>{mobile && <div className="fixed inset-0 z-50 bg-[#265048] p-6 text-[#deebe0] lg:hidden"><div className="flex items-center justify-between"><Logo light /><button onClick={() => setMobile(false)} data-testid="button-close-sidebar"><X /></button></div><div className="mt-10 flex flex-col gap-2">{[...navItems, ...moreItems].map(item => <SideLink key={item.href} {...item} active={location === item.href} onClick={() => setMobile(false)} />)}<button onClick={logout} className="mt-6 flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-[#abc1b3]" data-testid="button-mobile-logout"><span className="grid size-5 place-items-center rounded-md border border-[#6f9182] text-xs">↗</span>Log out</button></div></div>}<main className="mx-auto max-w-[1440px] px-5 py-7 lg:px-9 lg:py-10">{children}</main></div></div>;
}
function SideLink({ href, label, icon: Icon, active, onClick }: { href: string; label: string; icon: React.ComponentType<{ size?: number }>; active: boolean; onClick?: () => void }) { return <Link href={href} onClick={onClick} className={`mb-1 flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition-colors ${active ? 'bg-[#edbc55] text-[#20322f]' : 'text-[#abc1b3] hover:bg-[#305248] hover:text-[#f8f5eb]'}`} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} /><span>{label}</span>{label === 'Notifications' && <span className="ml-auto size-1.5 rounded-full bg-[#edbc55]" />}</Link>; }
function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="mb-8 flex flex-wrap items-end justify-between gap-5 animate-rise"><div>{eyebrow && <p className="mono mb-2 text-[10px] uppercase tracking-[.2em] text-[#b17820]">{eyebrow}</p>}<h1 className="display text-4xl font-bold tracking-[-.05em] text-[#20322f] md:text-5xl">{title}</h1>{description && <p className="mt-3 max-w-2xl text-sm leading-6 text-[#718079]">{description}</p>}</div>{action}</div>; }
function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-2xl border border-[#dbe4da] bg-[#fbfaf5] shadow-[var(--shadow-card)] ${className}`}>{children}</section>; }
function ProgressBar({ value, color = '#1e8f87' }: { value: number; color?: string }) { return <div className="h-2 overflow-hidden rounded-full bg-[#e3e9e1]"><div className="h-full rounded-full transition-all duration-500" style={{ width: `${value}%`, background: color }} /></div>; }
function Tag({ children, warm = false }: { children: React.ReactNode; warm?: boolean }) { return <span className={`inline-flex rounded-lg px-2 py-1 text-[10px] font-bold ${warm ? 'bg-[#fae9bb] text-[#93611a]' : 'bg-[#e3eee7] text-[#1e8f87]'}`}>{children}</span>; }

function Dashboard() { const [done, setDone] = useState(false); return <><PageHeading eyebrow="Tuesday, April 22" title="Good morning, Maya." description="You have a clear 25-minute win waiting. Keep the thread going." action={<Link href="/learning-path" className="inline-flex items-center gap-2 text-sm font-bold text-[#1e8f87]" data-testid="link-view-roadmap">View full roadmap <ArrowRight size={15} /></Link>} /><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Card className="overflow-hidden bg-[#265048] text-[#f8f5eb]"><div className="flex flex-col justify-between gap-8 p-6 md:flex-row md:p-8"><div><div className="flex items-center gap-2"><span className="size-2 rounded-full bg-[#edbc55]" /><p className="mono text-[10px] uppercase tracking-[.18em] text-[#b9d1c1]">Today’s focus · Deep Learning</p></div><h2 className="display mt-5 max-w-xl text-3xl font-bold tracking-[-.04em] md:text-4xl">Understand backpropagation</h2><p className="mt-3 max-w-lg text-sm leading-6 text-[#c0d3c7]">See how a network learns from its mistakes. This closes the last concept gap before you start building training loops.</p><div className="mt-7 flex flex-wrap items-center gap-3"><Button variant="warm" onClick={() => setDone(!done)}>{done ? <Check size={16} /> : <Play size={15} fill="currentColor" />} {done ? 'Completed for today' : 'Start 25 min lesson'}</Button><span className="flex items-center gap-1.5 text-xs text-[#b9d1c1]"><Clock3 size={14} /> 25 min · Video + notes</span></div></div><div className="grid size-28 shrink-0 place-items-center self-start rounded-full border-[10px] border-[#39645b] md:size-36" style={{ background: `conic-gradient(#edbc55 ${done ? 100 : 62}%, transparent 0)` }}><div className="grid size-[78px] place-items-center rounded-full bg-[#265048] md:size-[100px]"><span className="display text-2xl font-bold">{done ? '100' : '62'}<small className="text-sm">%</small></span></div></div></div></Card><Card className="p-6"><div className="flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[#82918a]">Path momentum</p><p className="mt-2 display text-3xl font-bold text-[#20322f]">74%</p></div><span className="grid size-10 place-items-center rounded-xl bg-[#fae9bb] text-[#a66c15]"><Flame size={19} /></span></div><ProgressBar value={74} color="#d89c2c" /><div className="mt-4 flex justify-between text-xs text-[#718079]"><span>12 day streak</span><span>+8% this week</span></div><div className="mt-6 rounded-xl bg-[#eef2ea] p-3 text-xs leading-5 text-[#61716c]"><span className="font-bold text-[#20322f]">Coach note:</span> You’re retaining more when you pair a concept with a small build.</div></Card></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.05fr_.95fr]"><Card><div className="flex items-center justify-between border-b border-[#e4e9e2] px-6 py-5"><div><h2 className="display text-xl font-bold">Your route</h2><p className="mt-1 text-xs text-[#7b8882]">Deep Learning is in motion</p></div><Link href="/learning-path" className="text-xs font-bold text-[#1e8f87]" data-testid="link-route-details">Details</Link></div><div className="p-6">{phases.map((phase, i) => <div key={phase.id} className="relative flex gap-4 pb-6 last:pb-0"><div className="relative flex flex-col items-center"><span className={`z-10 grid size-8 place-items-center rounded-full ${phase.status === 'complete' ? 'bg-[#1e8f87] text-[#f8f5eb]' : phase.status === 'current' ? 'border-2 border-[#edbc55] bg-[#fae9bb] text-[#a66c15]' : 'border border-[#ccd8ce] bg-[#f2f4ed] text-[#9aa7a0]'}`}>{phase.status === 'complete' ? <Check size={15} /> : <span className="text-xs font-bold">{i + 1}</span>}</span>{i !== phases.length - 1 && <span className="absolute top-8 h-full w-px bg-[#dbe4da]" />}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-3"><div><p className={`text-sm font-bold ${phase.status === 'current' ? 'text-[#1e8f87]' : 'text-[#40534d]'}`}>{phase.title}</p><p className="mt-1 text-xs text-[#83918a]">{phase.estimatedTime}</p></div><span className="mono text-xs text-[#88958e]">{phase.progress}%</span></div><ProgressBar value={phase.progress} color={phase.status === 'current' ? '#d89c2c' : '#1e8f87'} /></div></div>)}</div></Card><Card><div className="border-b border-[#e4e9e2] px-6 py-5"><h2 className="display text-xl font-bold">Skill signal</h2><p className="mt-1 text-xs text-[#7b8882]">Where your next hour pays off</p></div><div className="space-y-5 p-6">{[['Neural networks', 62, 78, 'priority'], ['PyTorch', 48, 70, 'priority'], ['Probability', 81, 75, 'strong']].map(([name, self, required, state]) => <div key={name as string}><div className="mb-2 flex items-center justify-between text-xs"><span className="font-bold text-[#40534d]">{name as string}</span><Tag warm={state === 'priority'}>{state === 'priority' ? 'Focus next' : 'On track'}</Tag></div><div className="relative"><ProgressBar value={self as number} color={state === 'priority' ? '#d89c2c' : '#1e8f87'} /><span className="absolute -top-1 size-4 rounded-full border-2 border-[#fbfaf5] bg-[#265048]" style={{ left: `calc(${required}% - 8px)` }} /></div><div className="mt-1 flex justify-between text-[10px] text-[#94a099]"><span>Current {self as number}</span><span>Role-ready {required as number}</span></div></div>)}</div><Link href="/skills" className="mx-6 mb-6 flex items-center justify-center gap-2 rounded-xl border border-[#ccd8ce] py-2.5 text-xs font-bold text-[#36504a]" data-testid="link-skill-intelligence">See skill intelligence <ArrowRight size={14} /></Link></Card></div></>; }

function LearningPath() { const [expanded, setExpanded] = useState('deep-learning'); return <><PageHeading eyebrow="Your personalized route" title="The path to AI Engineer" description="Four phases. One destination. The order is based on your current skills, not a generic curriculum." action={<Button variant="outline"><Download size={15} /> Export path</Button>} /><Card className="mb-5 flex flex-wrap items-center justify-between gap-5 bg-[#e4eee6] p-6"><div className="flex items-center gap-4"><span className="grid size-12 place-items-center rounded-2xl bg-[#1e8f87] text-[#f8f5eb]"><Target size={22} /></span><div><p className="text-xs font-bold uppercase tracking-wider text-[#718079]">Destination</p><p className="display text-2xl font-bold text-[#20322f]">Become an AI Engineer</p></div></div><div className="flex gap-8 text-right"><div><p className="mono text-xl font-medium text-[#1e8f87]">17 wks</p><p className="text-[10px] uppercase tracking-wider text-[#7c8b84]">estimated</p></div><div><p className="mono text-xl font-medium text-[#1e8f87]">74%</p><p className="text-[10px] uppercase tracking-wider text-[#7c8b84]">complete</p></div></div></Card><div className="space-y-3">{phases.map((phase, i) => <Card key={phase.id} className={`overflow-hidden ${phase.status === 'current' ? 'border-[#d9a43d]' : ''}`}><button onClick={() => setExpanded(expanded === phase.id ? '' : phase.id)} className="flex w-full items-center gap-4 p-5 text-left md:p-6" data-testid={`button-expand-phase-${phase.id}`}><span className={`grid size-10 shrink-0 place-items-center rounded-xl text-sm font-bold ${phase.status === 'complete' ? 'bg-[#dceee4] text-[#1e8f87]' : phase.status === 'current' ? 'bg-[#fae9bb] text-[#a66c15]' : 'bg-[#edf0eb] text-[#8b9891]'}`}>{phase.status === 'complete' ? <Check size={18} /> : `0${i + 1}`}</span><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center gap-2"><span className="display text-xl font-bold text-[#20322f]">{phase.title}</span>{phase.status === 'current' && <Tag warm>Current phase</Tag>}</span><span className="mt-1 block text-sm text-[#718079]">{phase.objective}</span></span><span className="hidden min-w-[120px] md:block"><ProgressBar value={phase.progress} color={phase.status === 'current' ? '#d89c2c' : '#1e8f87'} /><span className="mt-1 block text-right text-[10px] text-[#83918a]">{phase.progress}% complete</span></span><ChevronDown size={18} className={`text-[#86938c] transition-transform ${expanded === phase.id ? 'rotate-180' : ''}`} /></button>{expanded === phase.id && <div className="border-t border-[#e4e9e2] bg-[#f6f7f1] px-5 pb-6 pt-5 md:px-20"><div className="grid gap-6 md:grid-cols-[1fr_1fr]"><div><p className="mono text-[10px] uppercase tracking-widest text-[#b17820]">Skills in this phase</p><div className="mt-3 flex flex-wrap gap-2">{phase.skills.map(s => <Tag key={s}>{s}</Tag>)}</div></div><div><p className="mono text-[10px] uppercase tracking-widest text-[#b17820]">Proof of progress</p><p className="mt-3 text-sm font-bold text-[#40534d]">{phase.project}</p><p className="mt-1 text-xs text-[#83918a]">{phase.assessment} · {phase.estimatedTime}</p></div></div><Link href={phase.id === 'deep-learning' ? '/learning-path/deep-learning' : '/resources'} className="mt-6 inline-flex items-center gap-2 text-sm font-bold text-[#1e8f87]" data-testid={`link-phase-${phase.id}`}>{phase.status === 'current' ? 'Open phase details' : 'Preview this phase'} <ArrowRight size={15} /></Link></div>}</Card>)}</div></>; }

function DeepLearning() { const [completed, setCompleted] = useState(false); return <><Link href="/learning-path" className="mb-7 inline-flex items-center gap-2 text-sm font-bold text-[#61716c]" data-testid="link-back-path"><ChevronLeft size={16} /> Learning path</Link><PageHeading eyebrow="Phase 02 · 5 weeks" title="Deep Learning" description="Move from using models to understanding how they learn. This phase turns the black box into a system you can reason about." action={<Tag warm>62% complete</Tag>} /><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6 md:p-8"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[#fae9bb] text-[#a66c15]"><Zap size={18} /></span><div><p className="text-xs font-bold uppercase tracking-wider text-[#83918a]">The next milestone</p><h2 className="display text-2xl font-bold">Build your first training loop</h2></div></div><p className="mt-6 max-w-2xl text-sm leading-7 text-[#61716c]">You have the intuition. Now make it executable. Work through these three steps to connect forward passes, loss, and parameter updates.</p><div className="mt-7 space-y-3">{['Watch: how a neural network learns', 'Code: a training loop in PyTorch', 'Prove it: explain gradient descent in your own words'].map((item, i) => <button key={item} onClick={() => i === 2 && setCompleted(!completed)} className="flex w-full items-center gap-3 rounded-xl border border-[#dbe4da] bg-[#f8f8f2] p-4 text-left transition-colors hover:bg-[#eaf1e8]" data-testid={`button-milestone-${i}`}><span className={`grid size-7 place-items-center rounded-full ${i < 2 || completed ? 'bg-[#1e8f87] text-[#f8f5eb]' : 'border border-[#bfcfc2] text-[#9aa7a0]'}`}>{i < 2 || completed ? <Check size={14} /> : i + 1}</span><span className="text-sm font-bold text-[#40534d]">{item}</span>{i === 2 && <span className="ml-auto text-xs text-[#1e8f87]">{completed ? 'Done' : 'Mark complete'}</span>}</button>)}</div><div className="mt-7 flex items-center gap-3"><Button variant="warm"><Play size={15} fill="currentColor" /> Continue lesson</Button><Button variant="ghost">Ask assistant <ArrowRight size={14} /></Button></div></Card><Card className="p-6"><p className="mono text-[10px] uppercase tracking-widest text-[#b17820]">Why this, now?</p><h2 className="display mt-3 text-2xl font-bold">It unlocks Transformers.</h2><p className="mt-3 text-sm leading-7 text-[#718079]">Attention layers are easier to understand when you can already follow data through a network and diagnose a loss curve.</p><div className="mt-7 border-t border-[#e4e9e2] pt-5"><p className="text-xs font-bold text-[#40534d]">Your evidence</p><div className="mt-4 flex items-center gap-3"><span className="grid size-9 place-items-center rounded-xl bg-[#dceee4] text-[#1e8f87]"><ShieldCheck size={17} /></span><div><p className="text-sm font-bold">Probability is on track</p><p className="text-xs text-[#83918a]">84% checkpoint · 2 days ago</p></div></div></div></Card></div><Card className="mt-5 p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="display text-xl font-bold">Phase resources</h2><p className="mt-1 text-xs text-[#83918a]">Selected for your learning preference: short focused sessions</p></div><Link href="/resources" className="text-xs font-bold text-[#1e8f87]" data-testid="link-all-resources">Browse all</Link></div><div className="mt-5 grid gap-3 md:grid-cols-3">{initialResources.slice(0, 3).map(r => <ResourceMini key={r.id} resource={r} />)}</div></Card></>; }

function ResourceMini({ resource }: { resource: Resource }) { return <div className="rounded-xl border border-[#dbe4da] p-4"><div className="flex items-start justify-between"><Tag>{resource.type}</Tag><Star size={15} className="text-[#d89c2c]" fill="currentColor" /></div><p className="mt-4 text-sm font-bold leading-5 text-[#40534d]">{resource.title}</p><p className="mt-1 text-xs text-[#83918a]">{resource.source} · {resource.duration}</p></div>; }

function Resources({ saved, toggleSaved }: { saved: Resource[]; toggleSaved: (id: string) => void }) { const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All'); const [selected, setSelected] = useState<Resource | null>(null); const filtered = saved.filter(r => `${r.title} ${r.source} ${r.skills.join(' ')}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'All' || r.type === filter)); return <><PageHeading eyebrow="Curated for your route" title="Resource shelf" description="Less browsing, more learning. These are here because they help with the next skill on your path." /><div className="mb-6 flex flex-col gap-3 md:flex-row"><label className="relative flex-1"><Search size={17} className="absolute left-4 top-3.5 text-[#88958e]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search titles, skills, or sources" className="w-full rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] py-3 pl-11 pr-4 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-resource-search" /></label><select value={filter} onChange={e => setFilter(e.target.value)} className="rounded-xl border border-[#ccd8ce] bg-[#fbfaf5] px-4 py-3 text-sm font-bold text-[#40534d] outline-none" data-testid="select-resource-filter"><option>All</option><option>Article</option><option>Video series</option><option>Interactive</option><option>Workshop</option></select></div>{filtered.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map(r => <Card key={r.id} className="group p-5 transition-transform duration-200 hover:-translate-y-1"><div className="flex items-start justify-between"><div className="flex gap-2"><Tag>{r.type}</Tag><Tag warm>{r.difficulty}</Tag></div><button onClick={() => toggleSaved(r.id)} className={`rounded-lg p-1.5 ${r.saved ? 'text-[#d89c2c]' : 'text-[#9aa7a0] hover:text-[#d89c2c]'}`} data-testid={`button-save-resource-${r.id}`}>{r.saved ? <Star size={18} fill="currentColor" /> : <Star size={18} />}</button></div><h2 className="display mt-6 text-xl font-bold leading-tight text-[#20322f]">{r.title}</h2><p className="mt-2 text-xs text-[#83918a]">{r.source} · {r.duration} · <span className="text-[#d89c2c]">Rating {r.rating}</span></p><p className="mt-4 rounded-xl bg-[#eef2ea] p-3 text-xs leading-5 text-[#61716c]"><span className="font-bold text-[#36504a]">Why it’s here:</span> {r.reason}</p><div className="mt-5 flex items-center justify-between"><div className="flex flex-wrap gap-1">{r.skills.map(s => <span key={s} className="text-[10px] font-bold text-[#1e8f87]">#{s.replaceAll(' ', '')}</span>)}</div><button onClick={() => setSelected(r)} className="text-xs font-bold text-[#1e8f87]" data-testid={`button-explain-resource-${r.id}`}>Details</button></div></Card>)}</div> : <Card className="p-12 text-center"><Search className="mx-auto text-[#9aa7a0]" /><h2 className="display mt-4 text-xl font-bold">No resources match that search</h2><p className="mt-2 text-sm text-[#83918a]">Try a broader skill or clear the filter.</p><Button variant="ghost" className="mt-3" onClick={() => { setQuery(''); setFilter('All'); }}>Clear search</Button></Card>}{selected && <div className="fixed inset-0 z-50 grid place-items-center bg-[#20322f]/40 p-5" onClick={() => setSelected(null)}><div className="w-full max-w-lg rounded-2xl bg-[#fbfaf5] p-7 shadow-2xl" onClick={e => e.stopPropagation()}><div className="flex justify-between"><Tag>{selected.type}</Tag><button onClick={() => setSelected(null)} data-testid="button-close-resource"><X size={19} /></button></div><h2 className="display mt-5 text-3xl font-bold">{selected.title}</h2><p className="mt-2 text-sm text-[#83918a]">{selected.source} · {selected.duration}</p><div className="mt-6 rounded-xl bg-[#e4eee6] p-4 text-sm leading-6 text-[#40534d]"><span className="font-bold">Coach reasoning:</span> {selected.reason}. It maps directly to {selected.skills.join(' and ')} — the concepts your next project will ask you to use.</div><Button className="mt-6 w-full" onClick={() => { toggleSaved(selected.id); setSelected(null); }}>{selected.saved ? 'Remove from saved' : 'Save for later'}</Button></div></div>}</>; }

function Projects() { const [tab, setTab] = useState('Recommended'); const projects = [{ title: 'Build a RAG-Based Question Answering System', type: 'Capstone', time: '8–10 hours', skills: ['RAG', 'Evaluation', 'Python'], status: 'Recommended', reason: 'The clearest proof of your target role.' }, { title: 'Classify satellite imagery', type: 'Phase project', time: '4–6 hours', skills: ['PyTorch', 'CNNs'], status: 'Current', reason: 'The right-sized build for Deep Learning.' }, { title: 'Predict customer churn', type: 'Completed', time: '3–4 hours', skills: ['Scikit-learn', 'Metrics'], status: 'Completed', reason: 'Completed Apr 06 · strong result' }]; return <><PageHeading eyebrow="Proof, not just progress" title="Project studio" description="Projects turn a concept into evidence. Your recommendations are intentionally small enough to finish." action={<Button variant="outline"><Plus size={15} /> Add project</Button>} /><div className="mb-6 flex gap-1 rounded-xl bg-[#e6ebe4] p-1 md:w-fit">{['Recommended', 'Current', 'Completed'].map(t => <button key={t} onClick={() => setTab(t)} className={`rounded-lg px-4 py-2 text-xs font-bold ${tab === t ? 'bg-[#fbfaf5] text-[#20322f] shadow-sm' : 'text-[#7b8882]'}`} data-testid={`button-project-tab-${t.toLowerCase()}`}>{t}</button>)}</div><div className="grid gap-4 lg:grid-cols-2">{projects.filter(p => tab === 'Recommended' ? true : p.status === tab).map((p, i) => <Card key={p.title} className={`p-6 ${i === 0 && tab === 'Recommended' ? 'border-[#d9a43d] bg-[#fffaf0]' : ''}`}><div className="flex items-start justify-between gap-4"><div><Tag warm={p.status === 'Recommended'}>{p.type}</Tag><h2 className="display mt-4 text-2xl font-bold leading-tight">{p.title}</h2></div><button className="rounded-lg p-1 text-[#8c9892]" data-testid={`button-project-menu-${i}`}><MoreHorizontal size={18} /></button></div><p className="mt-4 text-sm leading-6 text-[#718079]"><span className="font-bold text-[#40534d]">Why this project:</span> {p.reason}</p><div className="mt-5 flex flex-wrap gap-2">{p.skills.map(s => <Tag key={s}>{s}</Tag>)}</div><div className="mt-6 flex items-center justify-between border-t border-[#e4e9e2] pt-4"><span className="flex items-center gap-1.5 text-xs text-[#83918a]"><Clock3 size={14} /> {p.time}</span>{p.status === 'Completed' ? <span className="flex items-center gap-1.5 text-xs font-bold text-[#1e8f87]"><Check size={14} /> Shipped</span> : <Button variant={p.status === 'Recommended' ? 'warm' : 'primary'}>{p.status === 'Current' ? 'Continue project' : 'Start project'} <ArrowRight size={14} /></Button>}</div></Card>)}</div></>; }

function Skills() { const [info, setInfo] = useState<string | null>(null); const skills = [{ name: 'Python for ML', self: 88, verified: 92, required: 80, confidence: 'High', status: 'Verified' }, { name: 'Probability', self: 76, verified: 84, required: 75, confidence: 'High', status: 'Verified' }, { name: 'Neural networks', self: 62, verified: 54, required: 78, confidence: 'Growing', status: 'Focus next' }, { name: 'PyTorch', self: 48, verified: 41, required: 70, confidence: 'Building', status: 'Focus next' }, { name: 'Transformers', self: 18, verified: 0, required: 66, confidence: 'New', status: 'Upcoming' }]; return <><PageHeading eyebrow="Evidence over guesswork" title="Skill intelligence" description="A side-by-side view of where you are, what the role needs, and how confident we are in the signal." /><Card className="overflow-hidden"><div className="grid grid-cols-[1.3fr_.7fr_.7fr_.7fr] border-b border-[#e4e9e2] bg-[#f0f3ed] px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-[#84918a] md:grid-cols-[1.5fr_.7fr_.7fr_.7fr_.7fr]"><span>Skill</span><span>Current</span><span>Role-ready</span><span className="hidden md:block">Confidence</span><span>Status</span></div>{skills.map((s, i) => <button key={s.name} className="grid w-full grid-cols-[1.3fr_.7fr_.7fr_.7fr] items-center border-b border-[#e8ece6] px-5 py-5 text-left last:border-0 hover:bg-[#f8f8f2] md:grid-cols-[1.5fr_.7fr_.7fr_.7fr_.7fr]" onClick={() => setInfo(info === s.name ? null : s.name)} data-testid={`button-skill-${i}`}><div><p className="text-sm font-bold text-[#40534d]">{s.name}</p><div className="mt-2 max-w-[160px]"><ProgressBar value={s.verified || s.self} color={s.status === 'Focus next' ? '#d89c2c' : '#1e8f87'} /></div></div><span className="mono text-sm text-[#61716c]">{s.verified || s.self}</span><span className="mono text-sm text-[#20322f]">{s.required}</span><span className="hidden text-xs text-[#718079] md:block">{s.confidence}</span><span><Tag warm={s.status === 'Focus next'}>{s.status}</Tag></span>{info === s.name && <div className="col-span-full mt-4 rounded-xl bg-[#eef2ea] p-3 text-xs leading-5 text-[#61716c]"><span className="font-bold text-[#36504a]">Coach read:</span> {s.status === 'Focus next' ? `This is ${s.required - (s.verified || s.self)} points from role-ready. It is the reason your current phase emphasizes practice over more reading.` : 'Your verified signal is comfortably above the role threshold. Keep this warm through project work.'}</div>}</button>)}</Card><div className="mt-5 grid gap-5 md:grid-cols-3"><Card className="p-5"><Gauge className="text-[#1e8f87]" size={20} /><p className="mono mt-5 text-3xl text-[#20322f]">86%</p><p className="mt-1 text-xs text-[#718079]">path confidence</p></Card><Card className="p-5"><ShieldCheck className="text-[#1e8f87]" size={20} /><p className="mono mt-5 text-3xl text-[#20322f]">3</p><p className="mt-1 text-xs text-[#718079]">verified strengths</p></Card><Card className="p-5"><Target className="text-[#d89c2c]" size={20} /><p className="mono mt-5 text-3xl text-[#20322f]">2</p><p className="mt-1 text-xs text-[#718079]">priority gaps</p></Card></div></>; }

function Progress() { return <><PageHeading eyebrow="Your learning signal" title="Progress with context" description="The story behind the numbers: more consistent hours, stronger checkpoints, and a path that is getting clearer." action={<Button variant="outline"><Download size={15} /> Download report</Button>} /><div className="grid gap-5 md:grid-cols-3"><Metric label="Learning hours" value="43.5" delta="+12% vs last month" icon={<Clock3 />} /><Metric label="Average checkpoint" value="86%" delta="+18 points since start" icon={<TrendingUp />} /><Metric label="Projects shipped" value="2" delta="1 in progress" icon={<BriefcaseBusiness />} /></div><Card className="mt-5 p-5 md:p-7"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="display text-xl font-bold">Momentum over time</h2><p className="mt-1 text-xs text-[#83918a]">Hours studied and checkpoint score</p></div><div className="flex gap-4 text-xs text-[#718079]"><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-[#1e8f87]" />Hours</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-[#d89c2c]" />Score</span></div></div><div className="mt-8 flex h-52 items-end gap-2 border-b border-l border-[#dbe4da] px-2 pb-0 md:gap-5">{chartData.map((d, i) => <div key={d.week} className="flex h-full flex-1 items-end justify-center gap-1"><div className="w-2 rounded-t-md bg-[#1e8f87] transition-all duration-500 hover:bg-[#d89c2c]" style={{ height: `${d.hours * 8}%` }} /><div className="w-2 rounded-t-md bg-[#edbc55]" style={{ height: `${d.score * .8}%` }} /><span className="absolute mt-[228px] hidden -translate-x-1/2 text-[9px] text-[#9aa7a0] md:block">{i % 2 === 0 ? d.week.replace('2025', '') : ''}</span></div>)}</div></Card><div className="mt-5 grid gap-5 lg:grid-cols-2"><Card className="p-6"><h2 className="display text-xl font-bold">This week’s pattern</h2><div className="mt-5 space-y-4">{[['Mon', 'Deep Learning lesson', '25 min', true], ['Tue', 'Implement a training loop', '45 min', true], ['Wed', 'Review: loss functions', '20 min', false], ['Thu', 'Checkpoint practice', '30 min', false]].map(([day, title, time, complete]) => <div key={day as string} className="flex items-center gap-3"><span className={`grid size-7 place-items-center rounded-full ${complete ? 'bg-[#dceee4] text-[#1e8f87]' : 'border border-[#ccd8ce] text-[#a1ada7]'}`}>{complete ? <Check size={14} /> : <span className="size-1.5 rounded-full bg-current" />}</span><span className="w-9 text-xs font-bold text-[#7b8882]">{day as string}</span><span className="flex-1 text-sm font-bold text-[#40534d]">{title as string}</span><span className="text-xs text-[#83918a]">{time as string}</span></div>)}</div></Card><Card className="bg-[#265048] p-6 text-[#f8f5eb]"><p className="mono text-[10px] uppercase tracking-widest text-[#edbc55]">Coach reflection</p><p className="display mt-5 text-2xl font-bold leading-tight">“Consistency is now doing more for you than intensity.”</p><p className="mt-5 text-sm leading-6 text-[#bcd0c2]">Your best weeks are the ones with four short sessions. The plan will keep protecting that rhythm.</p></Card></div></>; }
function Metric({ label, value, delta, icon }: { label: string; value: string; delta: string; icon: React.ReactNode }) { return <Card className="p-5"><span className="text-[#1e8f87] [&>svg]:size-5">{icon}</span><p className="mono mt-5 text-3xl text-[#20322f]">{value}</p><p className="mt-1 text-sm font-bold text-[#40534d]">{label}</p><p className="mt-2 text-xs text-[#1e8f87]">{delta}</p></Card>; }

function Assessments({ practice = false }: { practice?: boolean }) { const [active, setActive] = useState<Assessment | null>(null); const [q, setQ] = useState(0); const [finished, setFinished] = useState(false); return <><PageHeading eyebrow="Checkpoints, not judgments" title={practice ? 'Practice room' : 'Assessment history'} description={practice ? 'A low-stakes way to find the edge of your understanding.' : 'Use small assessments to turn confidence into evidence.'} />{active ? <Card className="mx-auto max-w-3xl p-6 md:p-10">{finished ? <div className="text-center"><span className="mx-auto grid size-16 place-items-center rounded-full bg-[#dceee4] text-[#1e8f87]"><Check size={28} /></span><p className="mono mt-6 text-xs uppercase tracking-widest text-[#b17820]">Checkpoint complete</p><h2 className="display mt-3 text-4xl font-bold">Nice work, Maya.</h2><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-[#718079]">You scored 84%. We’ll use this to shape the next recommendation on your path.</p><Button className="mt-7" onClick={() => { setActive(null); setFinished(false); setQ(0); }}>Back to assessments</Button></div> : <><div className="flex items-center justify-between"><Tag>{active.topic}</Tag><span className="text-xs text-[#83918a]">Question {q + 1} of {active.questions}</span></div><ProgressBar value={((q + 1) / active.questions) * 100} /><h2 className="display mt-10 text-3xl font-bold">What does the loss function tell you during training?</h2><p className="mt-3 text-sm text-[#718079]">Choose the answer that best explains the model’s current state.</p><div className="mt-7 space-y-3">{['How quickly the data was loaded', 'How far predictions are from the target', 'How many layers are in the network', 'Whether the model uses attention'].map((a, i) => <button key={a} onClick={() => { if (q + 1 >= 3) setFinished(true); else setQ(q + 1); }} className="flex w-full items-center gap-3 rounded-xl border border-[#dbe4da] p-4 text-left text-sm font-bold text-[#40534d] hover:border-[#1e8f87] hover:bg-[#eef2ea]" data-testid={`button-answer-${i}`}><span className="grid size-7 place-items-center rounded-lg bg-[#edf0eb] text-xs text-[#718079]">{String.fromCharCode(65 + i)}</span>{a}</button>)}</div></>}</Card> : <div className="grid gap-4">{assessments.map(a => <Card key={a.id} className="flex flex-wrap items-center gap-5 p-5 md:p-6"><span className={`grid size-11 place-items-center rounded-xl ${a.status === 'Passed' ? 'bg-[#dceee4] text-[#1e8f87]' : 'bg-[#fae9bb] text-[#a66c15]'}`}><ListChecks size={20} /></span><div className="min-w-[180px] flex-1"><h2 className="font-bold text-[#40534d]">{a.topic}</h2><p className="mt-1 text-xs text-[#83918a]">{a.questions} questions · {a.difficulty} · {a.date}</p></div><div className="mr-4"><p className="mono text-xl text-[#20322f]">{a.latestScore ? `${a.latestScore}%` : '—'}</p><p className="text-[10px] uppercase tracking-wider text-[#9aa7a0]">{a.latestScore ? 'latest score' : 'ready to take'}</p></div><Button variant={a.status === 'Passed' ? 'outline' : 'warm'} onClick={() => setActive(a)}>{a.status === 'Passed' ? 'Retake' : 'Start checkpoint'} <ArrowRight size={14} /></Button></Card>)}</div>}</>; }

function Assistant() { const [messages, setMessages] = useState([{ from: 'ai', text: 'Hi Maya. I’m looking at your Deep Learning phase with you. What feels murky right now?' }]); const [input, setInput] = useState(''); const send = (text = input) => { if (!text.trim()) return; setMessages([...messages, { from: 'you', text }, { from: 'ai', text: 'Try explaining it with a tiny example first. I can help you turn that into a 20-minute practice step.' }]); setInput(''); }; return <><PageHeading eyebrow="Your learning companion" title="Ask your coach" description="A calm place to untangle concepts, choose a next step, or think out loud." /><div className="grid gap-5 lg:grid-cols-[1fr_280px]"><Card className="flex min-h-[570px] flex-col overflow-hidden"><div className="flex items-center gap-3 border-b border-[#e4e9e2] px-6 py-4"><span className="grid size-9 place-items-center rounded-xl bg-[#dceee4] text-[#1e8f87]"><Bot size={18} /></span><div><p className="text-sm font-bold">Path coach</p><p className="text-[10px] text-[#83918a]">Context: Deep Learning · 62%</p></div><span className="ml-auto flex items-center gap-1.5 text-[10px] font-bold text-[#1e8f87]"><span className="size-1.5 rounded-full bg-[#1e8f87]" /> Local mock session</span></div><div className="flex-1 space-y-5 overflow-auto p-6">{messages.map((m, i) => <div key={i} className={`flex ${m.from === 'you' ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-6 ${m.from === 'you' ? 'rounded-br-md bg-[#1e8f87] text-[#f8f5eb]' : 'rounded-bl-md bg-[#eef2ea] text-[#40534d]'}`}>{m.text}</div></div>)}</div><div className="border-t border-[#e4e9e2] p-4"><div className="mb-3 flex flex-wrap gap-2">{['Explain backpropagation simply', 'What should I build next?', 'Quiz me on neural networks'].map(prompt => <button key={prompt} onClick={() => send(prompt)} className="rounded-lg border border-[#dbe4da] px-3 py-1.5 text-[11px] font-bold text-[#61716c] hover:border-[#1e8f87] hover:text-[#1e8f87]" data-testid={`button-prompt-${prompt.slice(0, 5)}`}>{prompt}</button>)}</div><form onSubmit={e => { e.preventDefault(); send(); }} className="flex gap-2"><input value={input} onChange={e => setInput(e.target.value)} placeholder="Ask about your path..." className="min-w-0 flex-1 rounded-xl border border-[#ccd8ce] bg-[#f9f9f3] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-assistant" /><Button type="submit" className="size-11 shrink-0 p-0"><Send size={16} /></Button></form></div></Card><Card className="h-fit p-5"><p className="mono text-[10px] uppercase tracking-widest text-[#b17820]">Learner context</p><h2 className="display mt-3 text-xl font-bold">Maya’s profile</h2><div className="mt-5 space-y-4 text-xs"><div><p className="text-[#9aa7a0]">Destination</p><p className="mt-1 font-bold text-[#40534d]">{learner.goal}</p></div><div><p className="text-[#9aa7a0]">Available time</p><p className="mt-1 font-bold text-[#40534d]">{learner.constraints[0]}</p></div><div><p className="text-[#9aa7a0]">Learning preference</p><p className="mt-1 font-bold text-[#40534d]">{learner.preferences.join(' + ')}</p></div></div><Link href="/profile" className="mt-6 flex items-center gap-2 text-xs font-bold text-[#1e8f87]" data-testid="link-edit-context">Edit context <ArrowRight size={14} /></Link></Card></div></>; }

function Profile({ settings = false }: { settings?: boolean }) { const [saved, setSaved] = useState(false); const [editing, setEditing] = useState(false); if (settings) return <><PageHeading eyebrow="Make it work for you" title="Settings" description="Tune the pace and the signals without losing your destination." /><div className="grid gap-5 lg:grid-cols-[1fr_280px]"><Card className="divide-y divide-[#e4e9e2]">{[['Weekly learning hours', 'Protect a realistic rhythm', '8 hours', Clock3], ['Daily reminders', 'A gentle nudge at your chosen time', 'Weekdays · 8:30 AM', Bell], ['Path adjustments', 'Let your plan adapt to progress', 'On', Sparkles]].map(([head, sub, value, Icon]) => <div key={head as string} className="flex items-center gap-4 p-6"><span className="grid size-10 place-items-center rounded-xl bg-[#e3eee7] text-[#1e8f87]"><Icon size={18} /></span><div className="flex-1"><p className="text-sm font-bold">{head as string}</p><p className="mt-1 text-xs text-[#83918a]">{sub as string}</p></div><button onClick={() => setSaved(true)} className="rounded-lg border border-[#ccd8ce] px-3 py-2 text-xs font-bold text-[#40534d]" data-testid={`button-setting-${head}`}>{value as string} <ChevronDown size={13} className="ml-1 inline" /></button></div>)}</Card><Card className="h-fit p-5"><ShieldCheck className="text-[#1e8f87]" size={20} /><h2 className="display mt-4 text-xl font-bold">Private by design</h2><p className="mt-2 text-xs leading-5 text-[#718079]">This first build keeps your profile and choices in local browser state. You stay in control.</p></Card></div>{saved && <p className="mt-4 text-xs font-bold text-[#1e8f87]">Preference saved locally.</p>}</>; return <><PageHeading eyebrow="Your learning identity" title="Maya Chen" description="The context behind your path. Update it when your direction changes." action={<Button onClick={() => setSaved(!saved)}>{saved ? <Check size={15} /> : null}{saved ? 'Saved' : 'Save changes'}</Button>} /><div className="grid gap-5 lg:grid-cols-[280px_1fr]"><Card className="p-6 text-center"><span className="mx-auto grid size-24 place-items-center rounded-[2rem] bg-[#edbc55] text-2xl font-bold text-[#20322f]">MC</span><h2 className="display mt-5 text-2xl font-bold">Maya Chen</h2><p className="mt-1 text-sm text-[#718079]">Learning since Feb 2025</p><div className="mt-6 flex justify-center gap-4 text-center"><div><p className="mono text-lg text-[#1e8f87]">12</p><p className="text-[10px] text-[#83918a]">day streak</p></div><div><p className="mono text-lg text-[#1e8f87]">2</p><p className="text-[10px] text-[#83918a]">projects</p></div></div></Card><Card className="p-6">{editing ? <form onSubmit={e => { e.preventDefault(); setEditing(false); setSaved(true); }} className="space-y-4"><p className="mono text-[10px] uppercase tracking-widest text-[#b17820]">Edit profile</p><label className="block text-sm font-bold text-[#36504a]">Full name<input defaultValue="Maya Chen" className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#f9f9f3] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-profile-name" /></label><label className="block text-sm font-bold text-[#36504a]">Current role<input defaultValue="Aspiring AI Engineer" className="mt-2 w-full rounded-xl border border-[#ccd8ce] bg-[#f9f9f3] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="input-profile-role" /></label><label className="block text-sm font-bold text-[#36504a]">About you<textarea defaultValue="I learn best by building small projects and explaining concepts back." rows={4} className="mt-2 w-full resize-none rounded-xl border border-[#ccd8ce] bg-[#f9f9f3] px-4 py-3 text-sm outline-none focus:border-[#1e8f87]" data-testid="textarea-profile-about" /></label><div className="flex gap-3"><Button type="submit">Save profile</Button><Button variant="ghost" onClick={() => setEditing(false)}>Cancel</Button></div></form> : <><p className="mono text-[10px] uppercase tracking-widest text-[#b17820]">Path context</p><div className="mt-5 grid gap-5 md:grid-cols-2">{[['Destination', learner.goal], ['Timeline', learner.timeline], ['Experience', learner.experience], ['Available time', learner.constraints[0]], ['Interests', learner.interests.join(' · ')], ['Preferences', learner.preferences.join(' · ')]].map(([a, b]) => <div key={a}><p className="text-xs text-[#9aa7a0]">{a}</p><p className="mt-1 text-sm font-bold text-[#40534d]">{b}</p></div>)}</div><div className="mt-6 rounded-xl bg-[#eef2ea] p-4"><p className="text-xs font-bold text-[#40534d]">About Maya</p><p className="mt-1 text-sm leading-6 text-[#61716c]">I learn best by building small projects and explaining concepts back.</p></div><Button variant="outline" className="mt-7" onClick={() => setEditing(true)} data-testid="button-edit-profile">Edit learner profile <ArrowRight size={14} /></Button></>}</Card></div>{saved && <p className="mt-4 text-xs font-bold text-[#1e8f87]">Profile saved locally.</p>}</>; }

function Notifications() { const [read, setRead] = useState<string[]>([]); const notices = [{ id: 'n1', icon: TrendingUp, title: 'Your checkpoint score moved up 16 points', body: 'That confirms you are ready to start training loops.', time: '2 hours ago' }, { id: 'n2', icon: Lightbulb, title: 'A new resource fits your pace', body: 'The Illustrated Transformer is a 35-minute visual bridge into your next phase.', time: 'Yesterday' }, { id: 'n3', icon: Flame, title: '12 day streak', body: 'Two more focused sessions keeps your current weekly rhythm.', time: 'Apr 20' }]; return <><PageHeading eyebrow="Small signals, useful at the right time" title="Notifications" description="Adaptive notices from your path coach." action={<Button variant="ghost" onClick={() => setRead(notices.map(n => n.id))}>Mark all read</Button>} /><div className="space-y-3">{notices.map(n => <Card key={n.id} className={`flex gap-4 p-5 transition-opacity ${read.includes(n.id) ? 'opacity-60' : ''}`}><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-[#e3eee7] text-[#1e8f87]"><n.icon size={18} /></span><div className="flex-1"><p className="text-sm font-bold">{n.title}</p><p className="mt-1 text-sm leading-6 text-[#718079]">{n.body}</p><p className="mono mt-3 text-[10px] text-[#9aa7a0]">{n.time}</p></div>{!read.includes(n.id) && <button onClick={() => setRead([...read, n.id])} className="size-2 rounded-full bg-[#d89c2c]" data-testid={`button-read-${n.id}`} />}</Card>)}</div></>; }

function LegacyOnboarding() { const [, setLocation] = useLocation(); const [step, setStep] = useState(0); const [choices, setChoices] = useState<Record<number, string[]>>({}); const [custom, setCustom] = useState<Record<number, string>>({}); const screens = [{ title: 'Where are you headed?', sub: 'A destination gives every recommendation a reason.', options: ['Become an AI Engineer', 'Become a Data Scientist', 'Build stronger technical foundations', 'Other'] }, { title: 'What do you already know?', sub: 'No judgment. This is how we avoid teaching you what you have already mastered.', options: ['Python and data analysis', 'Statistics and experimentation', 'I’m starting from the beginning', 'Other'] }, { title: 'How do you like to learn?', sub: 'We’ll shape the rhythm around the way your attention works.', options: ['Short focused sessions', 'Build as I learn', 'Deep dives on weekends'] }, { title: 'How much time is real?', sub: 'A sustainable path beats an impressive plan you cannot keep.', options: ['3–5 hours per week', '6–9 hours per week', '10+ hours per week'] }, { title: 'Review your starting point', sub: 'You can edit any of this later. Your path will get sharper after a short assessment.', options: [] }]; const choose = (o: string) => setChoices({ ...choices, [step]: [o] }); const isOther = choices[step]?.[0] === 'Other'; const customValue = custom[step] || ''; const canContinue = Boolean(choices[step]?.length && (!isOther || customValue.trim())); return <div className="min-h-[100dvh] bg-[#f7f5ed]"><header className="flex h-[72px] items-center justify-between border-b border-[#dbe4da] px-5 lg:px-10"><Logo /><span className="mono text-[10px] uppercase tracking-widest text-[#83918a]">Profile setup · {step + 1}/5</span></header><main className="mx-auto max-w-3xl px-5 py-14 md:py-20"><div className="mb-12 flex gap-1.5">{screens.map((_, i) => <span key={i} className={`h-1.5 flex-1 rounded-full ${i <= step ? 'bg-[#1e8f87]' : 'bg-[#dce4da]'}`} />)}</div>{step === 4 ? <Card className="p-7 md:p-10"><p className="mono text-xs uppercase tracking-[.18em] text-[#b17820]">Ready to begin</p><h1 className="display mt-4 text-4xl font-bold tracking-[-.05em]">Here’s what we heard.</h1><div className="mt-8 divide-y divide-[#e4e9e2]">{[['Destination', choices[0]?.[0] === 'Other' ? custom[0] : choices[0]?.[0] || 'Become an AI Engineer'], ['Experience', choices[1]?.[0] === 'Other' ? custom[1] : choices[1]?.[0] || 'Python and data analysis'], ['Learning rhythm', choices[2]?.[0] || 'Short focused sessions'], ['Weekly time', choices[3]?.[0] || '6–9 hours per week']].map(([a, b]) => <div key={a} className="flex justify-between gap-5 py-4"><span className="text-sm text-[#83918a]">{a}</span><span className="text-right text-sm font-bold">{b}</span></div>)}</div><Button className="mt-8 w-full" onClick={() => setLocation('/assessment')}>Take the 12-minute baseline <ArrowRight size={16} /></Button><p className="mt-4 text-center text-xs text-[#83918a]">Your answers stay in this browser for now.</p></Card> : <div className="animate-rise"><p className="mono text-xs uppercase tracking-[.18em] text-[#b17820]">Step {String(step + 1).padStart(2, '0')}</p><h1 className="display mt-4 text-5xl font-bold leading-tight tracking-[-.06em] text-[#20322f]">{screens[step].title}</h1><p className="mt-4 text-base leading-7 text-[#718079]">{screens[step].sub}</p><div className="mt-9 grid gap-3">{screens[step].options.map((o, i) => <button key={o} onClick={() => choose(o)} className={`flex items-center justify-between rounded-2xl border p-5 text-left transition-all ${choices[step]?.includes(o) ? 'border-[#1e8f87] bg-[#e4eee6] shadow-sm' : 'border-[#dbe4da] bg-[#fbfaf5] hover:border-[#9eb9a5]'}`} data-testid={`button-onboarding-option-${i}`}><span className="text-sm font-bold text-[#40534d]">{o}</span><span className={`grid size-7 place-items-center rounded-full border ${choices[step]?.includes(o) ? 'border-[#1e8f87] bg-[#1e8f87] text-[#f8f5eb]' : 'border-[#cbd8ce] text-transparent'}`}><Check size={14} /></span></button>)}{isOther && <div className="rounded-2xl border border-[#c7d8ca] bg-[#eaf1e8] p-5 animate-rise"><label className="block text-sm font-bold text-[#36504a]">{step === 0 ? 'Tell us about your destination' : 'Tell us about your background'}</label><p className="mt-1 text-xs leading-5 text-[#718079]">{step === 0 ? 'Share the role, outcome, or direction you have in mind.' : 'Add the skills, subjects, or experience you already have.'}</p><textarea autoFocus value={customValue} onChange={e => setCustom({ ...custom, [step]: e.target.value })} rows={4} placeholder={step === 0 ? 'e.g. I want to become a product designer in the next year.' : 'e.g. I have worked with JavaScript and built two web apps.'} className="mt-3 w-full resize-none rounded-xl border border-[#c7d8ca] bg-[#fbfaf5] px-4 py-3 text-sm outline-none focus:border-[#1e8f87] focus:ring-2 focus:ring-[#1e8f87]/10" data-testid={`textarea-onboarding-other-${step}`} /></div>}</div><div className="mt-10 flex items-center justify-between"><button onClick={() => setStep(Math.max(0, step - 1))} className="text-sm font-bold text-[#83918a]" data-testid="button-onboarding-back">{step > 0 ? 'Back' : 'Save and exit'}</button><Button disabled={!canContinue} onClick={() => setStep(step + 1)}>Continue <ArrowRight size={16} /></Button></div></div>}</main></div>; }

function AssessmentLanding() { const [, setLocation] = useLocation(); return <div className="min-h-[100dvh] bg-[#265048] px-5 py-8 text-[#f8f5eb]"><div className="mx-auto max-w-4xl"><Logo light /><div className="grid items-center gap-12 py-20 md:grid-cols-[1fr_330px]"><div><p className="mono text-xs uppercase tracking-[.2em] text-[#edbc55]">Baseline assessment</p><h1 className="display mt-5 text-5xl font-bold leading-[.95] tracking-[-.06em] md:text-7xl">Let’s find your <span className="text-[#edbc55]">starting line.</span></h1><p className="mt-7 max-w-lg text-base leading-7 text-[#c2d3c8]">12 minutes. 18 questions. No trick questions. We’re looking for the concepts you can use today so your path begins at the right altitude.</p><Button variant="warm" className="mt-9" onClick={() => setLocation('/assessments')}>Begin assessment <ArrowRight size={16} /></Button></div><div className="rounded-3xl border border-[#4e7068] bg-[#305248] p-6"><p className="mono text-[10px] uppercase tracking-widest text-[#9eb8aa]">You’ll explore</p>{['Python for ML', 'Probability', 'Model evaluation', 'Neural networks'].map((x, i) => <div key={x} className="flex items-center gap-3 border-b border-[#4e7068] py-4 last:border-0"><span className="mono text-xs text-[#edbc55]">0{i + 1}</span><span className="text-sm font-bold">{x}</span></div>)}<p className="mt-5 text-xs leading-5 text-[#9eb8aa]">You can pause between questions. Your route is not decided by one score.</p></div></div></div></div>; }

function AppRouter({ resources, toggleSaved }: { resources: Resource[]; toggleSaved: (id: string) => void }) {
  return <Switch><Route path="/" component={Landing} /><Route path="/how-it-works" component={HowItWorks} /><Route path="/features" component={Features} /><Route path="/about" component={About} /><Route path="/login"><Auth /></Route><Route path="/register"><Auth register /></Route><Route path="/onboarding" component={OnboardingSkills} /><Route path="/assessment" component={AssessmentLanding} /><Route path="/admin/login" component={AdminLogin} /><Route path="/admin/dashboard" component={AdminDashboard} /><Route path="/admin/users"><AdminModule module="users" /></Route><Route path="/admin/learning"><AdminModule module="learning" /></Route><Route path="/admin/learning-paths"><AdminModule module="learning-paths" /></Route><Route path="/admin/ai-controls"><AdminModule module="ai-controls" /></Route><Route path="/admin/audit"><AdminModule module="audit" /></Route><Route path="/admin/skills"><AdminModule module="skills" /></Route><Route path="/admin/assessments"><AdminModule module="assessments" /></Route><Route path="/admin/resources"><AdminModule module="resources" /></Route><Route path="/admin/recommendations"><AdminModule module="recommendations" /></Route><Route path="/admin/analytics"><AdminModule module="analytics" /></Route><Route path="/admin/notifications"><AdminModule module="notifications" /></Route><Route path="/admin/settings"><AdminModule module="settings" /></Route><Route path="/dashboard"><AppShell><Dashboard /></AppShell></Route><Route path="/learning-path"><AppShell><LearningPath /></AppShell></Route><Route path="/learning-path/deep-learning"><AppShell><DeepLearning /></AppShell></Route><Route path="/resources"><AppShell><Resources saved={resources} toggleSaved={toggleSaved} /></AppShell></Route><Route path="/projects"><AppShell><Projects /></AppShell></Route><Route path="/skills"><AppShell><Skills /></AppShell></Route><Route path="/progress"><AppShell><Progress /></AppShell></Route><Route path="/assessments"><AppShell><Assessments /></AppShell></Route><Route path="/assistant"><AppShell><Assistant /></AppShell></Route><Route path="/profile"><AppShell><Profile /></AppShell></Route><Route path="/settings"><AppShell><Profile settings /></AppShell></Route><Route path="/notifications"><AppShell><Notifications /></AppShell></Route><Route component={NotFound} /></Switch>;
}

function App() { const [resources, setResources] = useState(initialResources); const toggleSaved = (id: string) => setResources(current => current.map(r => r.id === id ? { ...r, saved: !r.saved } : r)); return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><AppRouter resources={resources} toggleSaved={toggleSaved} /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }

export default App;